#include <WiFi.h>
#include <Preferences.h>
#include <Wire.h>
#include <DHT.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// ============================================================
// ROCKETG.O LEARNING DESK - UNIFIED FIRMWARE
// ============================================================

// ---------- GPIO DEFINITIONS ----------
#define SDA_PIN       21
#define SCL_PIN       22
#define TRIG_PIN      5
#define ECHO_PIN      18  // LƯU Ý: Phải qua cầu phân áp 5V -> 3.3V trước khi cắm vào ESP32
#define LDR_PIN       34  // Hợp lệ: ADC1, Input-only
#define DHT_PIN       4
#define AQ_PIN        35  // Hợp lệ: ADC1, Input-only
#define START_PIN     26
#define STOP_PIN      27
#define RGB_R_PIN     14
#define RGB_G_PIN     32
#define RGB_B_PIN     33
#define BUZZER_PIN    25

#define DHTTYPE       DHT22

// ---------- TIMING & THRESHOLDS ----------
// NHẬP WIFI THỰC TẾ CỦA BẠN VÀO ĐÂY
const char* WIFI_SSID = "YOUR_WIFI_SSID";
const char* WIFI_PASSWORD = "YOUR_WIFI_PASSWORD";

const unsigned long WIFI_RECONNECT_INTERVAL = 5000;
const unsigned long SENSOR_READ_INTERVAL    = 2000; 
const unsigned long OLED_PAGE_INTERVAL      = 4000; 
const unsigned long BUTTON_DEBOUNCE         = 250;
const float PRESENCE_DISTANCE_MAX_CM        = 120.0;

// ---------- DATA STRUCTURES ----------
enum SystemState { STATE_IDLE, STATE_STUDYING };

struct EnvironmentData {
  float  temperature;
  float  humidity;
  bool   isTempHumValid;
  int    lightLevel;
  int    co2Ppm;
  bool   isCo2Valid;
  int    airQualityRaw;
  String airQualityStatus; 
};

struct IntegrityData {
  float currentDistance;
  bool  presenceDetected;
  bool  sensorError;
};

struct SystemHealth {
  uint32_t freeHeap;
  int32_t  wifiRssi;
  uint32_t uptimeSec;
};

Preferences preferences;
String deviceId;

wl_status_t lastWiFiStatus = WL_IDLE_STATUS;
SystemState currentState   = STATE_IDLE;

unsigned long sessionStartTime     = 0;
unsigned long lastReconnectAttempt = 0;
unsigned long lastSensorUpdate     = 0;
unsigned long lastStartPress       = 0;
unsigned long lastStopPress        = 0;

EnvironmentData  envData;
IntegrityData    integData;
SystemHealth     sysHealth;

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);
bool oledAvailable = false;

DHT dhtSensor(DHT_PIN, DHTTYPE);

void initializeDeviceIdentity() {
  preferences.begin("rocketgo", false);
  deviceId = preferences.getString("device_id", "");
  if (deviceId.isEmpty()) {
    uint64_t chipId = ESP.getEfuseMac();
    char buffer[32];
    snprintf(buffer, sizeof(buffer), "RG-%04X%08X", (uint16_t)(chipId >> 32), (uint32_t)chipId);
    deviceId = String(buffer);
    preferences.putString("device_id", deviceId);
  }
  Serial.println("[CORE] Device ID: " + deviceId);
}

void handleWiFi() {
  wl_status_t currentStatus = WiFi.status();
  if (currentStatus != lastWiFiStatus) {
    lastWiFiStatus = currentStatus;
    if (currentStatus == WL_CONNECTED) {
      Serial.println("[WIFI] Connected. IP: " + WiFi.localIP().toString());
    } else {
      Serial.println("[WIFI] Disconnected.");
    }
  }
  if (currentStatus != WL_CONNECTED && (millis() - lastReconnectAttempt >= WIFI_RECONNECT_INTERVAL)) {
    Serial.println("[WIFI] Reconnecting...");
    WiFi.disconnect();
    WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
    lastReconnectAttempt = millis();
  }
}

void updateHealthMetrics() {
  sysHealth.freeHeap = ESP.getFreeHeap();
  sysHealth.uptimeSec = millis() / 1000;
  sysHealth.wifiRssi = (WiFi.status() == WL_CONNECTED) ? WiFi.RSSI() : -100;
}

void initializeSensors() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(LDR_PIN, INPUT);
  pinMode(AQ_PIN, INPUT);

  dhtSensor.begin();

  envData.isTempHumValid = false;
  envData.isCo2Valid = false;
  envData.co2Ppm = -1;
  envData.airQualityStatus = "UNKNOWN";
  Serial.println("[SENSORS] Initialized (CO2 marked unavailable).");
}

void readEnvironment() {
  envData.lightLevel = analogRead(LDR_PIN);

  float t = dhtSensor.readTemperature();
  float h = dhtSensor.readHumidity();

  if (!isnan(t) && !isnan(h)) {
    envData.temperature = t;
    envData.humidity    = h;
    envData.isTempHumValid = true;
  } else {
    envData.isTempHumValid = false;
  }

  envData.airQualityRaw = analogRead(AQ_PIN);
  if (envData.airQualityRaw < 1500) envData.airQualityStatus = "GOOD";
  else if (envData.airQualityRaw < 2800) envData.airQualityStatus = "MODERATE";
  else envData.airQualityStatus = "POOR";
}

void readIntegrity() {
  digitalWrite(TRIG_PIN, LOW); delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH, 30000); 
  if (duration > 0) {
    integData.currentDistance = duration * 0.0343 / 2.0;
    integData.sensorError = false;
    integData.presenceDetected = (integData.currentDistance <= PRESENCE_DISTANCE_MAX_CM);
  } else {
    integData.currentDistance = -1.0; 
    integData.sensorError = true;
    integData.presenceDetected = false; 
  }
}

void setRGB(bool r, bool g, bool b) {
  digitalWrite(RGB_R_PIN, r ? HIGH : LOW);
  digitalWrite(RGB_G_PIN, g ? HIGH : LOW);
  digitalWrite(RGB_B_PIN, b ? HIGH : LOW);
}

void triggerBuzzer() {
  digitalWrite(BUZZER_PIN, HIGH);
  delay(50);
  digitalWrite(BUZZER_PIN, LOW);
}

void updateLEDState() {
  if (currentState == STATE_IDLE) setRGB(false, false, true); 
  else setRGB(false, true, false); 
}

void updateOLED() {
  if (!oledAvailable) return;
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.print(WiFi.status() == WL_CONNECTED ? "WIFI:ON " : "WIFI:OFF");
  display.print(currentState == STATE_STUDYING ? " ST:STUDY" : " ST:IDLE");
  display.drawLine(0, 10, 128, 10, SSD1306_WHITE);

  bool showEnvPage = (millis() / OLED_PAGE_INTERVAL) % 2 == 0;
  if (showEnvPage) {
    display.setCursor(0, 15);
    if (envData.isTempHumValid) display.printf("Temp: %.1f C\nHum : %.0f %%\n", envData.temperature, envData.humidity);
    else display.println("Temp: -- C\nHum : -- %");
    display.setCursor(0, 35);
    display.printf("Light: %d\nAir  : %s\nCO2  : N/A\n", envData.lightLevel, envData.airQualityStatus.c_str());
  } else {
    display.setCursor(0, 15);
    display.println("-- INTEGRITY & SYS --");
    display.setCursor(0, 30);
    if (!integData.sensorError) display.printf("Dist : %.1f cm\n", integData.currentDistance);
    else display.println("Dist : ERROR");
    display.printf("Pres : %s\n", integData.presenceDetected ? "YES" : "NO");
    display.printf("Heap : %u B\n", sysHealth.freeHeap);
  }
  display.display();
}

void handleButtons() {
  unsigned long now = millis();
  bool startPressed = (digitalRead(START_PIN) == LOW);
  bool stopPressed  = (digitalRead(STOP_PIN) == LOW);

  if (startPressed && (now - lastStartPress > BUTTON_DEBOUNCE)) {
    lastStartPress = now;
    if (currentState == STATE_IDLE) {
      currentState = STATE_STUDYING;
      sessionStartTime = now;
      triggerBuzzer();
      updateLEDState();
      updateOLED(); 
    }
  }
  if (stopPressed && (now - lastStopPress > BUTTON_DEBOUNCE)) {
    lastStopPress = now;
    if (currentState == STATE_STUDYING) {
      currentState = STATE_IDLE;
      triggerBuzzer();
      updateLEDState();
      updateOLED(); 
    }
  }
}

void sendTelemetry() {
  unsigned long sessionDuration = (currentState == STATE_STUDYING) ? (sysHealth.uptimeSec - (sessionStartTime / 1000)) : 0;
  char payload[512];
  snprintf(payload, sizeof(payload), 
    "{\"device_id\":\"%s\", \"state\":\"%s\", \"session_sec\":%lu, \"health\":{\"heap\":%u, \"rssi\":%ld, \"uptime\":%u}, \"integrity\":{\"presence\":%d, \"dist_cm\":%.1f, \"error\":%d}, \"environment\":{\"temp\":%.1f, \"hum\":%.1f, \"light\":%d, \"co2\":%d, \"aq\":\"%s\", \"valid\":%d}}",
    deviceId.c_str(),
    (currentState == STATE_STUDYING) ? "STUDYING" : "IDLE",
    sessionDuration,
    sysHealth.freeHeap,
    sysHealth.wifiRssi,
    sysHealth.uptimeSec,
    integData.presenceDetected ? 1 : 0,
    integData.currentDistance,
    integData.sensorError ? 1 : 0,
    envData.isTempHumValid ? envData.temperature : 0.0,
    envData.isTempHumValid ? envData.humidity : 0.0,
    envData.lightLevel,
    envData.co2Ppm,
    envData.airQualityStatus.c_str(),
    envData.isTempHumValid ? 1 : 0
  );
  Serial.print("[TELEMETRY] ");
  Serial.println(payload);
}

void setup() {
  Serial.begin(115200);
  delay(100);
  Serial.println("\n========================================");
  Serial.println("  ROCKETG.O LEARNING DESK - MASTER OS");
  Serial.println("========================================");

  initializeDeviceIdentity();
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  initializeSensors();

  pinMode(START_PIN, INPUT_PULLUP);
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(RGB_R_PIN, OUTPUT);
  pinMode(RGB_G_PIN, OUTPUT);
  pinMode(RGB_B_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);

  Wire.begin(SDA_PIN, SCL_PIN);
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("[OLED] Init Failed. Running Headless.");
    oledAvailable = false;
  } else {
    Serial.println("[OLED] Init Successful.");
    oledAvailable = true;
    display.clearDisplay();
    display.setTextSize(1);
    display.setTextColor(SSD1306_WHITE);
    display.setCursor(0, 25);
    display.println("System Ready.");
    display.display();
  }
  updateLEDState();
  Serial.println("[CORE] Boot Sequence Complete.");
}

void loop() {
  unsigned long now = millis();
  handleWiFi();
  handleButtons();
  if (now - lastSensorUpdate >= SENSOR_READ_INTERVAL) {
    lastSensorUpdate = now;
    updateHealthMetrics();
    readEnvironment();
    readIntegrity();
    updateOLED();
    sendTelemetry(); 
  }
}
